#Requires -Version 7.0
[CmdletBinding()]
param(
    [string]$Params,

    [string]$ParamsPath,

    [Parameter(ValueFromPipeline = $true)]
    [object]$InputObject,

    [Parameter(ValueFromRemainingArguments = $true)]
    [string[]]$RemainingArguments
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$scriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$pluginRoot = (Resolve-Path -LiteralPath (Join-Path $scriptDir '../..')).ProviderPath
$env:MCP_PLUGIN_ROOT = $pluginRoot
$env:MCP_PLUGIN_HOST = 'claude-code'

$resolveCacheDir = Join-Path $pluginRoot 'lib\resolve-cache-dir.ps1'
if (Test-Path -LiteralPath $resolveCacheDir -PathType Leaf) {
    . $resolveCacheDir
    $wrapperTempTarget = @(
        $env:MCP_WORKSPACE_PATH,
        $env:MCPSERVER_WORKSPACE_PATH,
        $env:CLAUDE_PROJECT_DIR,
        $env:CODEX_CWD,
        $env:CODEX_WORKSPACE_PATH,
        $env:GROK_WORKSPACE_PATH,
        (Get-Location).ProviderPath
    ) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1
    if ($wrapperTempTarget) {
        $wrapperTempAlign = Set-McpPluginSameVolumeTemp -TargetPath $wrapperTempTarget
        if ($wrapperTempAlign -and -not $wrapperTempAlign.Succeeded -and $wrapperTempAlign.Error) {
            [Console]::Error.WriteLine([string]$wrapperTempAlign.Error)
        }
    }
}

$hookParams = $Params
if (-not $hookParams -and $null -ne $InputObject) {
    if ($InputObject -is [string]) {
        $hookParams = [string]$InputObject
    } else {
        $hookParams = $InputObject | ConvertTo-Json -Depth 20 -Compress
    }
}

$hookArguments = @{
    HookName = 'health-check'
    HostName = 'claude-code'
    CacheMode = 'flat'
}
if ($hookParams) { $hookArguments.Params = $hookParams }
if ($ParamsPath) { $hookArguments.ParamsPath = $ParamsPath }

$hookScript = Join-Path $pluginRoot 'lib\plugin-hook.ps1'
if ('health-check' -eq 'code-verify') {
    $timeoutSeconds = 60
    if ($env:MCP_CODE_VERIFY_TIMEOUT_SECONDS) {
        $parsedTimeout = 0
        if ([int]::TryParse([string]$env:MCP_CODE_VERIFY_TIMEOUT_SECONDS, [ref]$parsedTimeout) -and $parsedTimeout -gt 0) {
            $timeoutSeconds = $parsedTimeout
        }
    }

    $psi = [System.Diagnostics.ProcessStartInfo]::new()
    $psi.FileName = (Get-Command pwsh -ErrorAction Stop).Source
    $psi.UseShellExecute = $false
    $psi.RedirectStandardInput = $true
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    $psi.CreateNoWindow = $true
    $psi.WorkingDirectory = (Get-Location).ProviderPath
    $psi.ArgumentList.Add('-NoLogo')
    $psi.ArgumentList.Add('-NoProfile')
    $psi.ArgumentList.Add('-NonInteractive')
    $psi.ArgumentList.Add('-File')
    $psi.ArgumentList.Add($hookScript)
    $psi.ArgumentList.Add('-HookName')
    $psi.ArgumentList.Add('health-check')
    $psi.ArgumentList.Add('-HostName')
    $psi.ArgumentList.Add('claude-code')
    $psi.ArgumentList.Add('-CacheMode')
    $psi.ArgumentList.Add('flat')
    if ($hookParams) {
        $psi.ArgumentList.Add('-Params')
        $psi.ArgumentList.Add($hookParams)
    }
    if ($ParamsPath) {
        $psi.ArgumentList.Add('-ParamsPath')
        $psi.ArgumentList.Add($ParamsPath)
    }
    foreach ($remaining in @($RemainingArguments)) {
        $psi.ArgumentList.Add($remaining)
    }

    $process = [System.Diagnostics.Process]::Start($psi)
    $stdinText = ''
    if ([Console]::IsInputRedirected) {
        $stdinText = [Console]::In.ReadToEnd()
    }
    if ($stdinText) {
        $process.StandardInput.Write($stdinText)
    }
    $process.StandardInput.Close()
    $stdoutTask = $process.StandardOutput.ReadToEndAsync()
    $stderrTask = $process.StandardError.ReadToEndAsync()
    if (-not $process.WaitForExit($timeoutSeconds * 1000)) {
        try { $process.Kill($true) } catch { }
        try { [void]$process.WaitForExit(2000) } catch { }
        Write-Output '{"status":"failed","code":"command_timeout"}'
        exit 0
    }

    $stderrText = ''
    try { $stderrText = [string]$stderrTask.Result } catch { }
    if ($stderrText) { [Console]::Error.Write($stderrText) }
    $stdoutText = ''
    try { $stdoutText = [string]$stdoutTask.Result } catch { }
    if ($stdoutText) { Write-Output $stdoutText.TrimEnd("`r", "`n") }
    exit $process.ExitCode
}

# TR-MCP-REPL-012 AC-001 (operator decision 2026-10-15 "Scope D1 to the hook process"): the deadline the hook publishes
# and the memory fetch timeout set below last only as long as this entry; a process that runs the entry in-process gets
# both back as they were when it returns.
$priorHookDeadline = $env:MCP_HOOK_DEADLINE_UTC_MS
$priorMemoryTimeout = $env:MCP_MEMORY_REPL_TIMEOUT_SECONDS
try {
    if ('health-check' -eq 'user-prompt-submit') {
        # TR-MCP-MEMORY-008 AC-002 (PLAN-SESSIONTRIAGEFIX-001 F2, triage-report-f01b3544): the request boundary adds the
        # plugin's required memories to the hook output, as this entry did before 2026-10-01, keeping the hook's own fields
        # and exit code. A missing helper or a failed fetch never blocks the prompt, and the fetch keeps to the hook
        # deadline (TR-MCP-REPL-012 AC-001): with under one second left it is not started, otherwise its timeout is no
        # longer than the whole seconds left.
        $hookOutput = & $hookScript @hookArguments @RemainingArguments
        $hookExit = if (Get-Variable -Name LASTEXITCODE -Scope Global -ErrorAction SilentlyContinue) { $global:LASTEXITCODE } else { 0 }
        $mergedOutput = ($hookOutput | Out-String).TrimEnd()
        try {
            $memoryContextScript = @('hooks/scripts/memory-context.ps1', 'lib/memory-context.ps1') |
                ForEach-Object { Join-Path $pluginRoot $_ } |
                Where-Object { Test-Path -LiteralPath $_ -PathType Leaf } |
                Select-Object -First 1
            if ($memoryContextScript) {
                . $memoryContextScript
                $injectArguments = @{ HookOutput = $mergedOutput; PluginRoot = $pluginRoot }
                $hookDeadline = 0L
                if ([long]::TryParse([string]$env:MCP_HOOK_DEADLINE_UTC_MS, [ref]$hookDeadline) -and $hookDeadline -gt 0) {
                    $remainingMs = $hookDeadline - [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds()
                    if ($remainingMs -lt 1000) {
                        $injectArguments.FetchOverride = { throw 'the hook deadline left no time to fetch required memories' }
                    } else {
                        $fetchSeconds = [long][Math]::Floor($remainingMs / 1000)
                        $ownSeconds = 0
                        if ([int]::TryParse([string]$env:MCP_MEMORY_REPL_TIMEOUT_SECONDS, [ref]$ownSeconds) -and $ownSeconds -gt 0 -and $ownSeconds -lt $fetchSeconds) {
                            $fetchSeconds = $ownSeconds
                        }
                        $env:MCP_MEMORY_REPL_TIMEOUT_SECONDS = [string]$fetchSeconds
                    }
                }
                $mergedOutput = Add-McpRequiredMemoryToHookOutput @injectArguments
            }
        } catch {
            [Console]::Error.WriteLine("required-memory injection skipped: $($_.Exception.Message)")
        }
        if (-not [string]::IsNullOrWhiteSpace($mergedOutput)) { Write-Output $mergedOutput }
        exit $hookExit
    }

    & $hookScript @hookArguments @RemainingArguments
    if (Get-Variable -Name LASTEXITCODE -Scope Global -ErrorAction SilentlyContinue) {
        exit $global:LASTEXITCODE
    }

    exit 0
} finally {
    if ($null -eq $priorHookDeadline) { Remove-Item -LiteralPath Env:MCP_HOOK_DEADLINE_UTC_MS -ErrorAction SilentlyContinue } else { $env:MCP_HOOK_DEADLINE_UTC_MS = $priorHookDeadline }
    if ($null -eq $priorMemoryTimeout) { Remove-Item -LiteralPath Env:MCP_MEMORY_REPL_TIMEOUT_SECONDS -ErrorAction SilentlyContinue } else { $env:MCP_MEMORY_REPL_TIMEOUT_SECONDS = $priorMemoryTimeout }
}

