94	function Join-McpBackgroundScopePath {
95	    <#
96	    .SYNOPSIS
97	        TR-MCP-PLUGIN-013 AC-005 (D3): the cache folder of one background host, <cache>/background/<key>. A key with characters other than
98	        letters, digits, dot, underscore and hyphen, or longer than 96 characters, is made file-safe and suffixed with a hash of the
99	        original, so two keys never share a folder.
100	    #>
101	    [CmdletBinding()]
102	    param(
103	        [Parameter(Mandatory)][string]$CacheDir,
104	        [Parameter(Mandatory)][string]$Key
105	    )
106	
107	    $safe = ($Key -replace '[^A-Za-z0-9._-]+', '-').Trim('-', '.')
108	    if ($safe -cne $Key -or $safe.Length -gt 96) {
109	        $hash = [System.Convert]::ToHexString([System.Security.Cryptography.SHA256]::HashData([System.Text.Encoding]::UTF8.GetBytes($Key))).Substring(0, 12).ToLowerInvariant()
110	        if ($safe.Length -gt 80) { $safe = $safe.Substring(0, 80) }
111	        $safe = if ($safe) { "$safe-$hash" } else { $hash }
112	    }
113	    return (Join-Path (Join-Path $CacheDir 'background') $safe)
114	}
