117	    <#
118	    .SYNOPSIS
119	        TR-MCP-PLUGIN-013 AC-005 (D3): the cache a session-log verb the agent calls itself uses. With no MCP_CACHE_DIR_OVERRIDE and with
120	        MCP_SUBAGENT_ID or GROK_SUBAGENT_ID set, that agent's background folder when it holds a current-turn.yaml; otherwise CacheDir.
121	        Those two are the only host identities an agent's own calls carry.
122	    #>
123	    [CmdletBinding()]
124	    param([Parameter(Mandatory)][string]$CacheDir)
125	
126	    if ($env:MCP_CACHE_DIR_OVERRIDE) { return $CacheDir }
127	    $key = @($env:MCP_SUBAGENT_ID, $env:GROK_SUBAGENT_ID) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1
128	    if ([string]::IsNullOrWhiteSpace($key)) { return $CacheDir }
129	    $scope = Join-McpBackgroundScopePath -CacheDir $CacheDir -Key $key.Trim()
130	    if (Test-Path -LiteralPath (Join-Path $scope 'current-turn.yaml') -PathType Leaf) { return $scope }
131	    return $CacheDir
132	}
