469	function Get-McpPluginWorkspaceTempDirectory {
470	    <#
471	    .SYNOPSIS
472	        FR-MCP-TEMPVOL-001: prefers workspace .mcpServer/tmp on the target volume.
473	    #>
474	    [CmdletBinding()]
475	    param([Parameter(Mandatory)][string]$TargetPath)
476	
477	    $dir = $TargetPath
478	    $isLeaf = $false
479	    try {
480	        $isLeaf = Test-Path -LiteralPath $TargetPath -PathType Leaf
481	    } catch {
482	        $isLeaf = $false
483	    }
484	    if ($isLeaf) {
485	        $dir = Split-Path -Parent $TargetPath
486	    }
487	
488	    $cursor = $dir
489	    for ($i = 0; $i -lt 20 -and -not [string]::IsNullOrWhiteSpace($cursor); $i++) {
490	        $marker = Join-Path $cursor 'AGENTS-README-FIRST.yaml'
491	        $markerExists = $false
492	        try {
493	            $markerExists = Test-Path -LiteralPath $marker -PathType Leaf
494	        } catch {
495	            $markerExists = $false
496	        }
497	        if ($markerExists) {
498	            return (Join-Path (Join-Path $cursor '.mcpServer') 'tmp')
499	        }
500	
501	        $parent = Split-Path -Parent $cursor
502	        if ([string]::IsNullOrWhiteSpace($parent) -or $parent -eq $cursor) { break }
503	        $cursor = $parent
504	    }
505	
506	    return (Join-Path (Join-Path $dir '.mcpServer') 'tmp')
507	}
