509	function Set-McpPluginSameVolumeTemp {
510	    <#
511	    .SYNOPSIS
512	        FR-MCP-TEMPVOL-001 / TR-MCP-TEMPVOL-001: align process TEMP and TMP to the target volume.
513	    .DESCRIPTION
514	        When TEMP/TMP are on a different volume than TargetPath, sets both to a writable
515	        directory on the target volume. Same-volume TEMP is left unchanged. A failed
516	        directory create does not mutate TEMP/TMP and returns Succeeded false with Error.
517	    #>
518	    [CmdletBinding()]
519	    param([Parameter(Mandatory)][string]$TargetPath)
520	
521	    $currentTemp = if (-not [string]::IsNullOrWhiteSpace($env:TEMP)) {
522	        $env:TEMP
523	    } elseif (-not [string]::IsNullOrWhiteSpace($env:TMP)) {
524	        $env:TMP
525	    } else {
526	        [System.IO.Path]::GetTempPath()
527	    }
528	
529	    $targetRoot = Get-McpPathVolumeRoot -Path $TargetPath
530	    $tempRoot = Get-McpPathVolumeRoot -Path $currentTemp
531	    if ($targetRoot -and $tempRoot -and $targetRoot.Equals($tempRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
532	        return (New-McpPluginTempAlignmentResult -Succeeded $true -Changed $false -TempPath $currentTemp)
533	    }
534	
535	    try {
536	        $alignedDir = Get-McpPluginWorkspaceTempDirectory -TargetPath $TargetPath
537	        [void][System.IO.Directory]::CreateDirectory($alignedDir)
538	        $probe = Join-Path $alignedDir ('.write-probe-' + [guid]::NewGuid().ToString('N'))
539	        [System.IO.File]::WriteAllText($probe, 'ok')
540	        [System.IO.File]::Delete($probe)
541	    } catch {
542	        return (New-McpPluginTempAlignmentResult -Succeeded $false -Changed $false -TempPath $currentTemp -ErrorMessage ('Unable to create writable TEMP on the workspace volume: ' + $_.Exception.Message))
543	    }
544	
545	    $resolved = [System.IO.Path]::GetFullPath($alignedDir)
546	    $env:TEMP = $resolved
547	    $env:TMP = $resolved
548	    [Environment]::SetEnvironmentVariable('TEMP', $resolved, 'Process')
549	    [Environment]::SetEnvironmentVariable('TMP', $resolved, 'Process')
550	    return (New-McpPluginTempAlignmentResult -Succeeded $true -Changed $true -TempPath $resolved)
551	}
552	
553	function Invoke-McpPluginReplacementMove {
554	    <#
555	    .SYNOPSIS
556	        FR-MCP-TEMPVOL-001: replacement move that never reports success when the destination is unchanged.
557	    .DESCRIPTION
558	        Cross-volume File.Move is refused with a visible Error. Exceptions and missing
559	        destinations also return Succeeded false. Preview-without-apply cannot look like success.
560	    #>
561	    [CmdletBinding()]
562	    param(
563	        [Parameter(Mandatory)][string]$SourcePath,
564	        [Parameter(Mandatory)][string]$DestinationPath
565	    )
566	
567	    $failed = {
568	        param([string]$Message)
569	        return [pscustomobject]@{
570	            Succeeded = $false
571	            Error = $Message
572	            DestinationUnchanged = $true
573	        }
574	    }
575	
576	    $srcRoot = $null
577	    $dstRoot = $null
578	    try { $srcRoot = Get-McpPathVolumeRoot -Path $SourcePath } catch { $srcRoot = $null }
579	    try { $dstRoot = Get-McpPathVolumeRoot -Path $DestinationPath } catch { $dstRoot = $null }
580	
581	    if ([string]::IsNullOrWhiteSpace($srcRoot) -or [string]::IsNullOrWhiteSpace($dstRoot)) {
582	        return (& $failed 'replacement move refused: source or destination volume could not be resolved')
583	    }
584	
585	    if (-not $srcRoot.Equals($dstRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
586	        return (& $failed 'cross-volume replacement move refused: TEMP/TMP must be on the destination volume')
587	    }
588	
589	    try {
590	        if (-not (Test-Path -LiteralPath $SourcePath -PathType Leaf)) {
591	            return (& $failed 'replacement move failed: source file is missing')
592	        }
593	
594	        $destDir = Split-Path -Parent $DestinationPath
595	        if ($destDir -and -not (Test-Path -LiteralPath $destDir -PathType Container)) {
596	            return (& $failed 'replacement move failed: destination directory is missing')
597	        }
598	
599	        [System.IO.File]::Move($SourcePath, $DestinationPath, $true)
600	    } catch {
601	        return (& $failed ('replacement move failed: ' + $_.Exception.Message))
602	    }
603	
604	    if (-not (Test-Path -LiteralPath $DestinationPath -PathType Leaf)) {
605	        return (& $failed 'replacement move failed: destination is missing after move')
606	    }
607	
608	    return [pscustomobject]@{
609	        Succeeded = $true
610	        Error = $null
611	        DestinationUnchanged = $false
612	    }
613	}
