#Requires -Version 7.0
# Round3 review tool 0: parser plus PSScriptAnalyzer (Warning, Error) over the reviewer's own tool scripts before they run.
[CmdletBinding()]
param(
    [string]$ToolDir = '<repo>/docs/receipts/hv/claude-opus-round3-tools'
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
Write-Output ("ANALYZE-TIME: {0}" -f (Get-Date -Format s))
$module = Get-Module -ListAvailable -Name PSScriptAnalyzer | Sort-Object Version -Descending | Select-Object -First 1
if ($null -eq $module) { Write-Output 'PSScriptAnalyzer: NOT AVAILABLE' } else { Write-Output ("PSScriptAnalyzer: {0}" -f $module.Version) }
foreach ($file in (Get-ChildItem -LiteralPath $ToolDir -Filter '*.ps1' -File | Sort-Object Name)) {
    $tokens = $null; $errors = $null
    [void][System.Management.Automation.Language.Parser]::ParseFile($file.FullName, [ref]$tokens, [ref]$errors)
    $parseCount = @($errors).Count
    $findings = @()
    if ($null -ne $module) {
        $findings = @(Invoke-ScriptAnalyzer -Path $file.FullName -Severity Warning, Error)
    }
    Write-Output ("{0}: parseErrors={1} analyzerFindings={2}" -f $file.Name, $parseCount, $findings.Count)
    foreach ($e in @($errors)) { Write-Output ("  PARSE L{0}: {1}" -f $e.Extent.StartLineNumber, $e.Message) }
    foreach ($f in $findings) { Write-Output ("  {0} L{1} {2}: {3}" -f $f.Severity, $f.Line, $f.RuleName, $f.Message) }
}

