#Requires -Version 7.0
# Round3 retry review tool A03: read-only reconciliation of (1) the prior Claude triage failsafe record,
# (2) live triage groups that match its dedupe key or title, and (3) the hook-opened ClaudeCode session turn.
[CmdletBinding()]
param(
    [string]$TurnRequestId = 'req-20261029T043640Z-prompt-f003',
    [string]$DedupeKey = 'wordpairs-health-timeout-20261028',
    [int]$HistoryLimit = 4
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$plugin = '<home>/github/mcpserver-claude-code-plugin'
$ws = '<repo>'
$wrapper = Join-Path $plugin 'lib/Invoke-McpPlugin.ps1'
Set-Location -LiteralPath $ws
Import-Module powershell-yaml -ErrorAction Stop

function Hide-McpSecret {
    param([string]$Text)
    $t = [regex]::Replace($Text, '(?i)(api[_-]?key["'':\s=]+)[A-Za-z0-9_\-]{20,}', '$1<redacted>')
    return [regex]::Replace($t, '(?i)(bearer\s+)[A-Za-z0-9._\-]{16,}', '$1<redacted>')
}

function Invoke-McpRead {
    param([string]$Method, [System.Collections.IDictionary]$Params)
    $raw = ''
    try {
        $raw = (& $wrapper -Command Invoke -Method $Method -ParamsObject $Params -WorkspacePath $ws -PluginRoot $plugin -TimeoutSeconds 180 2>&1 | Out-String)
    } catch {
        return [pscustomobject]@{ Ok = $false; Doc = $null; Raw = ('WRAPPER-ERROR: ' + $_.Exception.Message) }
    }
    $doc = $null
    try { $doc = ConvertFrom-Yaml -Yaml $raw -Ordered } catch { $doc = $null }
    if ($null -eq $doc) { try { $doc = $raw | ConvertFrom-Json -AsHashtable } catch { $doc = $null } }
    return [pscustomobject]@{ Ok = ($null -ne $doc); Doc = $doc; Raw = $raw }
}

Write-Output ("RECONCILE-TIME: {0}" -f (Get-Date -Format s))
Write-Output '== 1. Failsafe and triage YAML files anywhere under the workspace .mcpServer tree'
$mcpRoot = Join-Path $ws '.mcpServer'
$files = @(Get-ChildItem -LiteralPath $mcpRoot -Recurse -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.FullName -match '(?i)failsafe|triage|5ca5' })
Write-Output ("matchingFiles={0}" -f $files.Count)
foreach ($f in ($files | Sort-Object LastWriteTime | Select-Object -Last 40)) {
    Write-Output ("  {0} {1} bytes={2}" -f $f.LastWriteTime.ToString('s'), $f.FullName.Substring($ws.Length), $f.Length)
}

Write-Output '== 2. Live triage groups (pending and all) matching the prior dedupe key or /health title'
foreach ($status in @('', 'pending')) {
    $p = [ordered]@{ workspacePath = $ws }
    if ($status) { $p['status'] = $status }
    $r = Invoke-McpRead -Method 'workflow.triage.queryGroups' -Params $p
    if (-not $r.Ok) { Write-Output ("  queryGroups status='{0}': PARSE-FAILED {1}" -f $status, (Hide-McpSecret $r.Raw.Substring(0, [Math]::Min(800, $r.Raw.Length)))); continue }
    $json = $r.Doc | ConvertTo-Json -Depth 30 -Compress
    $hit = $json -match [regex]::Escape($DedupeKey) -or $json -match '(?i)health hangs'
    Write-Output ("  queryGroups status='{0}': length={1} mentionsPriorReport={2}" -f $status, $json.Length, $hit)
    if ($hit) {
        foreach ($m in [regex]::Matches($json, '.{0,400}(' + [regex]::Escape($DedupeKey) + '|health hangs).{0,400}', 'IgnoreCase')) {
            Write-Output ('    ' + (Hide-McpSecret $m.Value))
        }
    }
}

Write-Output '== 3. Session history for ClaudeCode (live server)'
$h = Invoke-McpRead -Method 'workflow.sessionlog.queryHistory' -Params ([ordered]@{ agent = 'ClaudeCode'; limit = $HistoryLimit; offset = 0 })
if (-not $h.Ok) {
    Write-Output ('  PARSE-FAILED ' + (Hide-McpSecret $h.Raw.Substring(0, [Math]::Min(1500, $h.Raw.Length))))
} else {
    $json = $h.Doc | ConvertTo-Json -Depth 40 -Compress
    Write-Output ("  historyLength={0} mentionsTurn={1}" -f $json.Length, ($json -match [regex]::Escape($TurnRequestId)))
    foreach ($m in [regex]::Matches($json, '"(sessionId|requestId|status|queryTitle|title|turnCount|lastUpdated|started)":("[^"]{0,160}"|\d+)')) {
        Write-Output ('    ' + $m.Value)
    }
}

