#Requires -Version 7.0
# Round3 retry review tool A06: read-only git inspection of the reviewed range. Never mutates the repository.
# Modes: Summary (HEAD, tracked-change check, log, name-status, stat), Diff (patch for the given paths),
# Show (file content at a revision), Log (per-path history with dates).
[CmdletBinding()]
param(
    [ValidateSet('Summary', 'Diff', 'Show', 'Log')]
    [string]$Mode = 'Summary',
    [string]$Base = '8e2f62417e0fe46cefd884e8a61024b12860a2cf',
    [string]$Head = '1c2272714fb02091e390f751510341e6824e3d22',
    [string[]]$Paths = @()
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$ws = '<repo>'
function Invoke-Git { param([string[]]$GitArgs) & git -C $ws --no-pager @GitArgs 2>&1 }
switch ($Mode) {
    'Summary' {
        Write-Output ("GIT-TIME: {0}" -f (Get-Date -Format s))
        Write-Output ("HEAD: {0}" -f (Invoke-Git @('rev-parse', 'HEAD')))
        $tracked = @(Invoke-Git @('status', '--porcelain', '--untracked-files=no'))
        Write-Output ("TRACKED-CHANGES: {0}" -f @($tracked | Where-Object { $_ }).Count)
        foreach ($t in $tracked) { if ($t) { Write-Output ("  {0}" -f $t) } }
        Write-Output '== log (base..head)'
        Invoke-Git @('log', '--format=%h %ad %an | %s', '--date=format-local:%Y-%m-%dT%H:%M:%S', "$Base..$Head")
        Write-Output '== name-status'
        Invoke-Git @('diff', '--name-status', "$Base..$Head")
        Write-Output '== shortstat'
        Invoke-Git @('diff', '--shortstat', "$Base..$Head")
    }
    'Diff' {
        Invoke-Git (@('diff', "$Base..$Head", '--') + $Paths)
    }
    'Show' {
        foreach ($p in $Paths) { Write-Output ("=== {0}:{1}" -f $Head, $p); Invoke-Git @('show', "${Head}:$p") }
    }
    'Log' {
        Invoke-Git (@('log', '--format=%h %ad | %s', '--date=format-local:%Y-%m-%dT%H:%M:%S', '--name-status', "$Base..$Head", '--') + $Paths)
    }
}

