# Round3 retry review tool A09: read-only summary of every retained run under the guest-admin-recovery evidence
# tree: validation/receipt status, revision, times, JUnit totals and non-passing case names.
[CmdletBinding()]
param()
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$root = '<repo>/docs/evidence/hosting/guest-admin-recovery'
Write-Output ("HISTORY-TIME: {0}" -f (Get-Date -Format s))
foreach ($dir in (Get-ChildItem -LiteralPath $root -Directory | Sort-Object { ($_.GetFiles() | Measure-Object LastWriteTime -Minimum).Minimum })) {
    Write-Output ("== {0}" -f $dir.Name)
    foreach ($jf in @(Get-ChildItem -LiteralPath $dir.FullName -File -Filter '*.json')) {
        try {
            $j = Get-Content -LiteralPath $jf.FullName -Raw | ConvertFrom-Json
            $props = @($j.PSObject.Properties | Where-Object { $_.Value -isnot [System.Array] -and $_.Value -isnot [pscustomobject] } | ForEach-Object { '{0}={1}' -f $_.Name, $_.Value })
            Write-Output ("  {0}: {1}" -f $jf.Name, ($props -join ' | '))
            if ($j.PSObject.Properties.Name -contains 'steps') {
                foreach ($s in $j.steps) { Write-Output ("    step {0} exit={1}" -f $s.name, $s.exitCode) }
            }
        } catch { Write-Output ("  {0}: PARSE-FAILED" -f $jf.Name) }
    }
    foreach ($xf in @(Get-ChildItem -LiteralPath $dir.FullName -File -Filter '*.xml')) {
        try {
            [xml]$x = Get-Content -LiteralPath $xf.FullName -Raw
            $cases = @($x.SelectNodes('//testcase'))
            $fail = @($cases | Where-Object { $_.SelectSingleNode('failure') -or $_.SelectSingleNode('error') })
            $skip = @($cases | Where-Object { $_.SelectSingleNode('skipped') })
            $stamp = @($x.SelectNodes('//testsuite') | ForEach-Object { $_.GetAttribute('timestamp') } | Where-Object { $_ } | Sort-Object | Select-Object -First 1)
            Write-Output ("  {0}: cases={1} failed={2} skipped={3} firstSuite={4} mtime={5}" -f $xf.Name, $cases.Count, $fail.Count, $skip.Count, ($stamp -join ''), $xf.LastWriteTime.ToString('s'))
            foreach ($c in $fail) { Write-Output ("    FAILED {0} :: {1}" -f $c.GetAttribute('classname'), $c.GetAttribute('name')) }
            foreach ($c in $skip) { Write-Output ("    SKIPPED {0} :: {1}" -f $c.GetAttribute('classname'), $c.GetAttribute('name')) }
        } catch { Write-Output ("  {0}: PARSE-FAILED" -f $xf.Name) }
    }
}

