import { failure } from "../../../domain/result";
import {
  getIdentityService,
  oidcAvailable,
} from "../../../infrastructure/runtime";
import {
  cookie,
  errorResponse,
  jsonInput,
  PRIVATE_HEADERS,
  sameOrigin,
  sessionCookie,
  uiSessionGeneration,
} from "../../../web/server-http";
export const runtime = "nodejs";
export async function GET(request: Request) {
  const service = getIdentityService();
  if (!service) return errorResponse(failure("TEMPORARY_UNAVAILABLE"));
  const result = await service.session(cookie(request, "wp_session"));
  return result.ok
    ? Response.json(
        {
          profile: result.value.profile,
          permissions: [],
          oidcAvailable: oidcAvailable(),
          sessionGeneration: uiSessionGeneration(cookie(request, "wp_session")),
        },
        { headers: PRIVATE_HEADERS },
      )
    : errorResponse(result);
}
export async function POST(request: Request) {
  if (!sameOrigin(request)) return errorResponse(failure("NOT_AUTHORIZED"));
  const input = await jsonInput(request);
  if (!input || Object.keys(input).some((key) => key !== "guestCredential"))
    return errorResponse(failure("VALIDATION_ERROR"));
  const service = getIdentityService();
  if (!service) return errorResponse(failure("TEMPORARY_UNAVAILABLE"));
  const result = await service.guest(input.guestCredential);
  return result.ok
    ? Response.json(
        {
          profile: result.value.profile,
          guestCredential: result.value.guestCredential,
          sessionGeneration: uiSessionGeneration(result.value.sessionToken),
        },
        {
          headers: {
            ...PRIVATE_HEADERS,
            "Set-Cookie": sessionCookie(
              request,
              "wp_session",
              result.value.sessionToken,
              2592000,
            ),
          },
        },
      )
    : errorResponse(result);
}
export async function DELETE(request: Request) {
  if (!sameOrigin(request)) return errorResponse(failure("NOT_AUTHORIZED"));
  const service = getIdentityService();
  if (!service) return errorResponse(failure("TEMPORARY_UNAVAILABLE"));
  const result = await service.logout(cookie(request, "wp_session"));
  return result.ok
    ? new Response(null, {
        status: 204,
        headers: {
          ...PRIVATE_HEADERS,
          "Set-Cookie": sessionCookie(request, "wp_session", "", 0),
        },
      })
    : errorResponse(result);
}

import { failure } from "../../../domain/result";
import {
  deliverOutbox,
  getIdentityService,
  getProfileStore,
} from "../../../infrastructure/runtime";
import { secrets } from "../../../infrastructure/secrets";
import {
  cookie,
  errorResponse,
  jsonInput,
  PRIVATE_HEADERS,
  sameOrigin,
} from "../../../web/server-http";
export const runtime = "nodejs";
export async function PATCH(request: Request) {
  if (!sameOrigin(request)) return errorResponse(failure("NOT_AUTHORIZED"));
  const service = getIdentityService();
  const store = getProfileStore();
  if (!service || !store)
    return errorResponse(failure("TEMPORARY_UNAVAILABLE"));
  const session = await service.session(cookie(request, "wp_session"));
  if (!session.ok) return errorResponse(session);
  const input = await jsonInput(request);
  if (
    !input ||
    Object.keys(input).some(
      (key) =>
        ![
          "commandId",
          "expectedVersion",
          "expectedProfileId",
          "icon",
          "publicLeaderboard",
          "regenerateAlias",
        ].includes(key),
    ) ||
    typeof input.expectedProfileId !== "string" ||
    typeof input.commandId !== "string" ||
    !/^[A-Za-z0-9_-]{1,128}$/.test(input.commandId) ||
    !Number.isSafeInteger(input.expectedVersion) ||
    (input.expectedVersion as number) < 0
  )
    return errorResponse(failure("VALIDATION_ERROR"));
  if (input.expectedProfileId !== session.value.actor.profileId)
    return errorResponse(failure("CONFLICT"));
  const preferences = {
    icon: input.icon,
    publicLeaderboard: input.publicLeaderboard,
    regenerateAlias: input.regenerateAlias,
  };
  const profileId = session.value.actor.profileId;
  const result = await service.preferences(
    {
      aggregateId: profileId,
      actorId: profileId,
      commandId: input.commandId,
      expectedVersion: input.expectedVersion as number,
      requestDigest: secrets.hash(
        JSON.stringify([
          input.icon ?? null,
          input.publicLeaderboard ?? null,
          input.regenerateAlias ?? null,
        ]),
      ),
    },
    session.value.actor,
    preferences,
    store,
  );
  if (result.ok) await deliverOutbox();
  return result.ok
    ? Response.json({ profile: result.value }, { headers: PRIVATE_HEADERS })
    : errorResponse(result);
}

import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  async headers() {
    return [
      {
        source: "/sw.js",
        headers: [
          {
            key: "Content-Type",
            value: "application/javascript; charset=utf-8",
          },
          {
            key: "Cache-Control",
            value: "no-cache, no-store, must-revalidate",
          },
          { key: "Service-Worker-Allowed", value: "/" },
          { key: "X-Content-Type-Options", value: "nosniff" },
        ],
      },
      {
        source: "/admin-sw.js",
        headers: [
          {
            key: "Content-Type",
            value: "application/javascript; charset=utf-8",
          },
          {
            key: "Cache-Control",
            value: "no-cache, no-store, must-revalidate",
          },
          { key: "Service-Worker-Allowed", value: "/admin" },
          { key: "X-Content-Type-Options", value: "nosniff" },
        ],
      },
    ];
  },
};

export default nextConfig;

/* Retire the formerly public game PWA. No fetch handler or private caching. */
self.addEventListener("install", event => {
  event.waitUntil(self.skipWaiting());
});
self.addEventListener("activate", event => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter(key => key.startsWith("wordpairs-pwa-")).map(key => caches.delete(key)));
    await self.registration.unregister();
  })());
});

/* Only static, public, explicitly listed files belong in this cache. */
const CACHE_NAME = "wordpairs-admin-pwa-v1";
const OFFLINE_URL = "/admin-offline.html";
const STATIC_FILES = [
  OFFLINE_URL,
  "/icons/icon-192.png",
  "/icons/icon-512.png",
  "/icons/maskable-512.png",
  "/icons/apple-touch-icon.png",
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => cache.addAll(STATIC_FILES)),
  );
  // Do not skipWaiting: an update must not take over an active game.
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then(async (keys) => {
      await Promise.all(
        keys
          .filter(
            (key) => key.startsWith("wordpairs-admin-pwa-") && key !== CACHE_NAME,
          )
          .map((key) => caches.delete(key)),
      );
      await self.clients.claim();
    }),
  );
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  const url = new URL(request.url);
  // Exclude API/auth endpoints even when directly opened as a document.
  if (
    request.method !== "GET" ||
    url.origin !== self.location.origin ||
    /^\/(api|auth)(\/|$)/.test(url.pathname)
  )
    return;
  if ((url.pathname !== "/admin" && !url.pathname.startsWith("/admin/")) || request.mode !== "navigate") return;
  event.respondWith(
    fetch(request).catch(async () => {
      const cached = await (await caches.open(CACHE_NAME)).match(OFFLINE_URL);
      return (
        cached ||
        new Response("You are offline. Reconnect to administer Wordpairs.", {
          status: 503,
          headers: { "Content-Type": "text/plain; charset=utf-8" },
        })
      );
    }),
  );
});

import adminManifest from "../../../web/admin-manifest";
export async function GET() {
  return Response.json(adminManifest(), {
    headers: {
      "Content-Type": "application/manifest+json",
      "Cache-Control": "public, max-age=60",
    },
  });
}

import type { Metadata } from "next";
import Link from "next/link";
import type { ReactNode } from "react";
export const metadata: Metadata = {
  title: "Wordpairs Admin",
  manifest: "/admin/manifest.webmanifest",
  appleWebApp: {
    capable: true,
    title: "Wordpairs Admin",
    statusBarStyle: "default",
  },
};
export default function AdminLayout({ children }: { children: ReactNode }) {
  return (
    <main className="site-shell">
      <header className="topbar">
        <Link className="brand" href="/">
          wordpairs
        </Link>
        <nav aria-label="Main navigation">
          <Link href="/play">Find a room</Link>
        </nav>
      </header>
      {children}
    </main>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

interface InstallPrompt extends Event {
  prompt(): Promise<void>;
  userChoice: Promise<{ outcome: "accepted" | "dismissed" }>;
}

export function PwaSupport() {
  const [installed, setInstalled] = useState(true);
  const [secure, setSecure] = useState(true);
  const [installPrompt, setInstallPrompt] = useState<InstallPrompt | null>(
    null,
  );
  const [message, setMessage] = useState("");
  const prompting = useRef(false);

  useEffect(() => {
    let active = true;
    const media = window.matchMedia("(display-mode: standalone)");
    const isInstalled = () =>
      media.matches ||
      ("standalone" in navigator && navigator.standalone === true);
    const modeChanged = () => setInstalled(isInstalled());
    const ready = (event: Event) => {
      event.preventDefault();
      setInstallPrompt(event as InstallPrompt);
    };
    const appInstalled = () => {
      setInstalled(true);
      setInstallPrompt(null);
    };
    modeChanged();
    setSecure(window.isSecureContext);
    window.addEventListener("beforeinstallprompt", ready);
    window.addEventListener("appinstalled", appInstalled);
    media.addEventListener("change", modeChanged);
    if (window.isSecureContext && "serviceWorker" in navigator) {
      navigator.serviceWorker
        .register("/admin-sw.js", { scope: "/admin", updateViaCache: "none" })
        .catch(() => {
          if (active)
            setMessage(
              "Installation support could not start. Reload to retry, or use your browser’s install menu.",
            );
        });
    }
    return () => {
      active = false;
      window.removeEventListener("beforeinstallprompt", ready);
      window.removeEventListener("appinstalled", appInstalled);
      media.removeEventListener("change", modeChanged);
    };
  }, []);

  async function install() {
    if (!installPrompt || prompting.current) return;
    const event = installPrompt;
    prompting.current = true;
    setInstallPrompt(null);
    try {
      await event.prompt();
      const choice = await event.userChoice;
      setMessage(
        choice.outcome === "accepted"
          ? "Finish installing in your browser’s prompt."
          : "You can install later from your browser’s menu.",
      );
    } catch {
      setMessage("Use your browser’s install menu or the instructions below.");
    } finally {
      prompting.current = false;
    }
  }

  if (installed) return null;
  return (
    <aside
      className="site-shell pwa-install"
      aria-label="Install Wordpairs Admin"
    >
      {secure && installPrompt && (
        <button type="button" onClick={install}>
          Install Wordpairs Admin
        </button>
      )}
      <details>
        <summary>Get Wordpairs Admin on your phone</summary>
        <p>
          <strong>iPhone:</strong> Open this site in Safari, tap Share, then Add
          to Home Screen. Keep Open as Web App enabled if offered.
        </p>
        <p>
          <strong>Android:</strong> Open your browser’s menu and choose Install
          app or Add to Home screen. The wording depends on your browser.
        </p>
        <p>
          Opens administration from your home screen. A connection and GitHub
          sign-in are required.
        </p>
      </details>
      {!secure && (
        <p>
          Installation requires a secure HTTPS address. Localhost is supported
          for development.
        </p>
      )}
      {message && <p role="status">{message}</p>}
    </aside>
  );
}
/** Retire only the former public-game worker/cache; leave admin and other apps intact. */
export function LegacyPwaCleanup() {
  useEffect(() => {
    if ("serviceWorker" in navigator) {
      void navigator.serviceWorker
        .getRegistrations()
        .then(async (registrations) => {
          for (const registration of registrations) {
            const worker =
              registration.active ??
              registration.waiting ??
              registration.installing;
            if (
              new URL(registration.scope).pathname === "/" &&
              worker &&
              new URL(worker.scriptURL).pathname === "/sw.js"
            )
              await registration.unregister();
          }
        })
        .catch(() => {});
    }
    if (typeof caches !== "undefined") {
      void caches
        .keys()
        .then((keys) =>
          Promise.all(
            keys
              .filter((key) => key.startsWith("wordpairs-pwa-"))
              .map((key) => caches.delete(key)),
          ),
        )
        .catch(() => {});
    }
  }, []);
  return null;
}

import type { MetadataRoute } from "next";

export default function adminManifest(): MetadataRoute.Manifest {
  return {
    id: "/admin",
    name: "Wordpairs Admin",
    short_name: "Wordpairs Admin",
    description: "Private Wordpairs administration for sharpninja.",
    lang: "en",
    start_url: "/admin",
    scope: "/admin",
    display: "standalone",
    background_color: "#f7f5ed",
    theme_color: "#142c32",
    icons: [
      {
        src: "/icons/icon-192.png",
        sizes: "192x192",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icons/icon-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icons/maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}

import type { Metadata, Viewport } from "next";
import type { ReactNode } from "react";
import { LegacyPwaCleanup } from "../web/pwa-support";
import "./globals.css";

export const metadata: Metadata = {
  title: "Wordpairs",
  description: "A real-time word association game.",
  applicationName: "Wordpairs",
  appleWebApp: {
    capable: false,
    title: "Wordpairs",
    statusBarStyle: "default",
  },
  icons: {
    icon: "/icons/icon-192.png",
    apple: "/icons/apple-touch-icon.png",
  },
};

export const viewport: Viewport = {
  themeColor: "#142c32",
  width: "device-width",
  initialScale: 1,
  viewportFit: "cover",
};

export default function RootLayout({
  children,
}: Readonly<{ children: ReactNode }>) {
  return (
    <html lang="en">
      <body>
        {children}
        <LegacyPwaCleanup />
      </body>
    </html>
  );
}

