import { githubAdminAvailable } from "../../infrastructure/runtime";
import { ContentScreen } from "../../web/content-panel";
export const dynamic = "force-dynamic";
export default function AdministrationPage() {
  return <ContentScreen oidcEnabled={githubAdminAvailable()} administration />;
}

"use client";
import Link from "next/link";
import { useCallback, useEffect, useRef, useState } from "react";
import { type OwnProfile, PROFILE_ICONS } from "../application/identity";
import type { Permission } from "../domain/access";
import { guestCredential } from "./guest-credential";
import { usePrivateDraftState } from "./private-draft";
import { bindPrivateIdentity } from "./private-state";
import { PwaSupport } from "./pwa-support";
import { usePrivateIntent } from "./use-private-intent";

const ICONS: Record<string, string> = {
  owl: "🦉",
  fox: "🦊",
  frog: "🐸",
  cat: "🐈",
  whale: "🐳",
  bee: "🐝",
};
export function ProfileIcon({ icon }: { icon: string }) {
  return (
    <span role="img" aria-label={icon}>
      {ICONS[icon] ?? "●"}
    </span>
  );
}
export function IdentityPanel({
  oidcEnabled,
  onProfile,
  administration = false,
}: {
  oidcEnabled: boolean;
  onProfile?: (profile: OwnProfile | null) => void;
  administration?: boolean;
}) {
  const [profile, setProfile] = useState<OwnProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [initialized, setInitialized] = useState(false);
  const [signInFailed, setSignInFailed] = useState(false);
  const [permissions, setPermissions] = useState<Permission[]>([]);
  const generation = useRef(0);
  const running = useRef(false);
  const endpoint = administration ? "/api/admin/session" : "/api/session";
  useEffect(() => {
    setSignInFailed(
      administration &&
        new URL(window.location.href).searchParams.get("auth") === "failed",
    );
  }, [administration]);
  const accept = useCallback(
    (
      current: OwnProfile | null,
      sessionGeneration?: string,
      grants: Permission[] = [],
    ) => {
      bindPrivateIdentity(current?.id ?? null, sessionGeneration);
      setProfile(current);
      setPermissions(administration && current ? grants : []);
      onProfile?.(current);
    },
    [onProfile, administration],
  );
  const load = useCallback(
    async (quiet = false) => {
      if (quiet && running.current) return;
      const sequence = ++generation.current;
      if (!quiet) setLoading(true);
      setError("");
      try {
        const response = await fetch(endpoint, {
          cache: "no-store",
          signal: AbortSignal.timeout(10000),
        });
        if (!response.ok && response.status !== 401)
          throw new Error("Unavailable");
        const result = response.ok ? await response.json() : null;
        if (!response.ok) await response.text();
        if (sequence === generation.current)
          accept(
            result?.profile ?? null,
            result?.sessionGeneration ?? undefined,
            Array.isArray(result?.permissions) ? result.permissions : [],
          );
      } catch {
        if (sequence === generation.current) {
          setPermissions([]);
          setError("Your profile is unavailable. Try again.");
        }
      } finally {
        if (sequence === generation.current) {
          setLoading(false);
          setInitialized(true);
        }
      }
    },
    [accept, endpoint],
  );
  useEffect(() => {
    void load();
    const timer = setInterval(() => void load(true), 15000);
    const focus = () => {
      if (running.current) return;
      setPermissions([]);
      void load();
    };
    window.addEventListener("focus", focus);
    return () => {
      clearInterval(timer);
      window.removeEventListener("focus", focus);
      generation.current++;
    };
  }, [load]);
  const session = async (method: "POST" | "DELETE") => {
    if (running.current) return;
    running.current = true;
    const sequence = ++generation.current;
    setLoading(true);
    setPermissions([]);
    setError("");
    try {
      const body =
        method === "POST"
          ? JSON.stringify({ guestCredential: await guestCredential() })
          : undefined;
      const response = await fetch(endpoint, {
        method,
        signal: AbortSignal.timeout(10000),
        headers: { "Content-Type": "application/json" },
        body,
      });
      if (!response.ok) throw new Error("Unavailable");
      const result = method === "POST" ? await response.json() : null;
      if (sequence === generation.current) {
        accept(result?.profile ?? null, result?.sessionGeneration ?? undefined);
        if (method === "POST") await load();
      }
    } catch {
      if (sequence === generation.current)
        setError(
          method === "POST"
            ? "Could not continue as guest. Check your connection and allow browser site data, then try again."
            : "Could not sign out. Try again.",
        );
    } finally {
      running.current = false;
      if (sequence === generation.current) setLoading(false);
    }
  };
  return (
    <section
      className="panel identity-panel"
      aria-labelledby="profile-heading"
      aria-busy={loading}
    >
      <p className="eyebrow">Make yourself at home</p>
      <h1 id="profile-heading">
        {administration
          ? "Administration"
          : profile
            ? "Your player profile"
            : "Ready for some wordplay?"}
      </h1>
      {error && (
        <p role="alert">
          {error}{" "}
          <button type="button" disabled={loading} onClick={() => void load()}>
            Retry profile
          </button>
        </p>
      )}
      {signInFailed && !profile && (
        <p role="alert">
          GitHub sign-in was not accepted. Only sharpninja can administer
          Wordpairs. Try signing in again.
        </p>
      )}
      {loading && <p role="status">Loading your profile…</p>}
      {profile ? (
        <>
          <p className="profile-alias">
            <ProfileIcon icon={profile.icon} /> <strong>{profile.alias}</strong>
          </p>
          <p>
            {profile.kind === "guest"
              ? "Guest profile saved in this browser."
              : "Signed-in profile."}{" "}
            {profile.wins} lifetime wins · {profile.points} points
          </p>
          <details>
            <summary>Profile details</summary>
            <p className="admin-id">
              Profile ID: <code>{profile.id}</code>
            </p>
            {permissions.includes("moderate") && !administration && (
              <Link href="/admin">Administration</Link>
            )}
          </details>
          {administration && permissions.length > 0 && (
            <nav className="admin-nav" aria-label="Administration">
              {permissions.includes("moderate") && (
                <Link href="/admin">Moderation</Link>
              )}
              {permissions.includes("manage-content") && (
                <Link href="/admin/words">Word pairs and hints</Link>
              )}
            </nav>
          )}
          {administration && permissions.includes("moderate") && <PwaSupport />}
          {!administration && (
            <ProfilePreferences
              key={profile.id}
              profile={profile}
              loading={loading}
              refresh={load}
              denied={() => accept(null)}
            />
          )}
          <div className="hero-actions">
            <button
              type="button"
              disabled={loading}
              onClick={() => void session("DELETE")}
            >
              Sign out
            </button>
          </div>
          {profile.kind === "guest" && (
            <p className="panel-note">
              Clearing this browser’s site data resets your guest identity.
            </p>
          )}
        </>
      ) : (
        <>
          <p>
            {administration
              ? "Administration is restricted to the GitHub account sharpninja."
              : "Play as a guest in this browser. No account is needed."}
          </p>
          <div className="hero-actions">
            {!administration && (
              <button
                type="button"
                className="button"
                disabled={loading || !initialized}
                onClick={() => void session("POST")}
              >
                Continue as guest
              </button>
            )}
            {administration && <AdminSignIn enabled={oidcEnabled} />}
          </div>
        </>
      )}
    </section>
  );
}
function AdminSignIn({ enabled }: { enabled: boolean }) {
  return enabled ? (
    <a className="button secondary" href="/api/auth/github/login">
      Sign in with GitHub
    </a>
  ) : (
    <div>
      <button
        type="button"
        className="button secondary"
        disabled
        aria-describedby="github-unavailable"
      >
        Sign in with GitHub
      </button>
      <p id="github-unavailable" className="panel-note">
        GitHub administrator sign-in is being configured.
      </p>
    </div>
  );
}
function ProfilePreferences({
  profile,
  loading,
  refresh,
  denied,
}: {
  profile: OwnProfile;
  loading: boolean;
  refresh: () => Promise<void>;
  denied: () => void;
}) {
  const intent = usePrivateIntent(profile.id, refresh, denied, "profile");
  const [editing, setEditing, clearEditing] = usePrivateDraftState<{
    icon: string;
    publicLeaderboard: boolean;
    regenerateAlias: boolean;
  } | null>(profile.id, "profile-editor", null);
  const opener = useRef<HTMLButtonElement>(null);
  const dialog = useRef<HTMLDialogElement>(null);
  const editingOpen = editing !== null;
  useEffect(() => {
    const modal = dialog.current;
    if (editingOpen && modal && !modal.open) modal.showModal();
    return () => {
      if (modal?.open) modal.close();
    };
  }, [editingOpen]);
  const restoreFocus = useRef(false);
  useEffect(() => {
    if (!editing && !loading && !intent.locked && restoreFocus.current) {
      restoreFocus.current = false;
      opener.current?.focus();
    }
  }, [editing, loading, intent.locked]);
  const update = (input: Record<string, unknown>, draftKey?: string) =>
    intent.send(
      "/api/profile",
      {
        ...input,
        expectedVersion: profile.version,
      },
      draftKey,
      "PATCH",
    );
  return (
    <>
      {!editing && intent.error && <p role="alert">{intent.error}</p>}
      {!editing && intent.notice && <p role="status">{intent.notice}</p>}
      {!editing && intent.busy && <p role="status">Saving your profile…</p>}
      <fieldset disabled={loading || intent.locked || !!editing}>
        <legend>Choose your icon</legend>
        <div className="icon-picker">
          {PROFILE_ICONS.map((icon) => (
            <button
              key={icon}
              type="button"
              aria-label={`Choose ${icon}`}
              aria-pressed={profile.icon === icon}
              onClick={() => void update({ icon })}
            >
              <ProfileIcon icon={icon} />
            </button>
          ))}
        </div>
      </fieldset>
      <label className="checkbox-label">
        <input
          type="checkbox"
          checked={profile.publicLeaderboard}
          disabled={loading || intent.locked || !!editing}
          onChange={(event) =>
            void update({ publicLeaderboard: event.target.checked })
          }
        />{" "}
        Show my generated alias on the public leaderboard
      </label>
      <div className="hero-actions">
        <button
          type="button"
          disabled={loading || intent.locked || !!editing}
          onClick={() => void update({ regenerateAlias: true })}
        >
          Generate another alias
        </button>
        <button
          ref={opener}
          type="button"
          disabled={loading || intent.locked || !!editing}
          onClick={() =>
            setEditing({
              icon: profile.icon,
              publicLeaderboard: profile.publicLeaderboard,
              regenerateAlias: false,
            })
          }
        >
          Edit profile
        </button>
      </div>
      {editing && (
        <dialog
          ref={dialog}
          aria-labelledby="edit-profile-title"
          onCancel={(event) => {
            event.preventDefault();
            if (!intent.locked) {
              restoreFocus.current = true;
              clearEditing();
            }
          }}
        >
          <h2 id="edit-profile-title">Edit profile</h2>
          {intent.error && <p role="alert">{intent.error}</p>}
          {intent.busy && <p role="status">Saving your profile…</p>}
          <form
            onSubmit={(event) => {
              event.preventDefault();
              restoreFocus.current = true;
              void update(editing, "profile-editor");
            }}
          >
            <fieldset disabled={loading || intent.locked}>
              <legend>Edit profile preferences</legend>
              <p>
                Saved alias: {profile.alias}. A new alias is generated only when
                you save.
              </p>
              <label>
                Draft profile icon
                <select
                  value={editing.icon}
                  onChange={(event) =>
                    setEditing({ ...editing, icon: event.target.value })
                  }
                >
                  {PROFILE_ICONS.map((icon) => (
                    <option key={icon} value={icon}>
                      {icon}
                    </option>
                  ))}
                </select>
              </label>
              <label className="checkbox-label">
                <input
                  type="checkbox"
                  checked={editing.regenerateAlias}
                  onChange={(event) =>
                    setEditing({
                      ...editing,
                      regenerateAlias: event.target.checked,
                    })
                  }
                />
                Generate a new alias on Save
              </label>
              <label className="checkbox-label">
                <input
                  type="checkbox"
                  checked={editing.publicLeaderboard}
                  onChange={(event) =>
                    setEditing({
                      ...editing,
                      publicLeaderboard: event.target.checked,
                    })
                  }
                />
                Publish alias on Save
              </label>
              <button type="submit">Save profile</button>
              <button
                type="button"
                onClick={() => {
                  restoreFocus.current = true;
                  clearEditing();
                }}
              >
                Cancel profile editing
              </button>
            </fieldset>
          </form>
          {intent.pending && (
            <button
              type="button"
              disabled={intent.busy}
              onClick={() => void intent.send()}
            >
              Retry profile update
            </button>
          )}
        </dialog>
      )}
      {!editing && intent.pending && (
        <button
          type="button"
          disabled={intent.busy}
          onClick={() => void intent.send()}
        >
          Retry profile update
        </button>
      )}
    </>
  );
}

#Requires -Version 7.0
[CmdletBinding(SupportsShouldProcess)]
param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop'
$entries=@(foreach($name in @('Convert-JUnitToTrx.ps1','Test-JUnitToTrx.ps1')){
    $path=Join-Path $PSScriptRoot $name
    $parserErrors=$null
    [void][Management.Automation.Language.Parser]::ParseFile($path,[ref]$null,[ref]$parserErrors)
    $analyzerIssues=@(Invoke-ScriptAnalyzer -Path $path -Severity Warning,Error)
    [pscustomobject]@{
        path=('scripts/'+$name)
        sha256=(Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash
        parserErrorCount=@($parserErrors).Count
        analyzerWarningErrorCount=$analyzerIssues.Count
        parserErrors=@($parserErrors|ForEach-Object Message)
        analyzerIssues=@($analyzerIssues|ForEach-Object {[pscustomobject]@{rule=$_.RuleName;line=$_.Line;message=$_.Message}})
    }
})
$receipt=[pscustomobject]@{
    timestamp=Get-Date -Format s
    entries=$entries
    totalParserErrors=@($entries|Where-Object parserErrorCount -GT 0).Count
    totalAnalyzerIssues=@($entries|Where-Object analyzerWarningErrorCount -GT 0).Count
    qualification='Current parser/analyzer status before the immediately subsequent adapter fixture rerun; does not backdate historical runs.'
}
if($PSCmdlet.ShouldProcess($OutputPath,'Write analyzer receipt for the exact adapter bytes')){
    $receipt|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $OutputPath
}
$receipt|ConvertTo-Json -Depth 8
if($receipt.totalParserErrors -or $receipt.totalAnalyzerIssues){throw 'Adapter analyzer gate failed.'}

#Requires -Version 7.0
# Round2 review step 7: read live QBrain requirements via the Claude plugin wrapper (read-only methods only).
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$plugin = '<home>/github/mcpserver-claude-code-plugin'
$ws = '<repo>'
$wrapper = Join-Path $plugin 'lib/Invoke-McpPlugin.ps1'
$out = Join-Path $ws 'docs/receipts/hv/claude-opus-round2-tools/qbrain-readback'
[void][IO.Directory]::CreateDirectory($out)
Set-Location -LiteralPath $ws
. (Join-Path $plugin 'lib/yaml-object-mutation.ps1')
Import-McpYamlSerializer
$bom = [string][char]0xFEFF
function Invoke-Read([string]$Method, $Params, [string]$Label) {
    $raw = & $wrapper -Command Invoke -Method $Method -ParamsObject $Params -WorkspacePath $ws -PluginRoot $plugin 2>&1
    $text = ($raw | Out-String).Replace($bom, '')
    [IO.File]::WriteAllText((Join-Path $out ($Label + '.yaml')), $text)
    try { return (ConvertFrom-Yaml -Yaml $text -ErrorAction Stop) } catch { Write-Output ("PARSE-FAIL {0}: {1}" -f $Label, $text.Substring(0, [Math]::Min(300, $text.Length))); return $null }
}
function Get-Field($Obj, [string]$Name) {
    if ($null -eq $Obj) { return $null }
    if ($Obj -is [System.Collections.IDictionary]) { if ($Obj.Contains($Name)) { return , $Obj[$Name] } else { return $null } }
    return $null
}
$layers = Invoke-Read 'workflow.requirements.listLayers' ([ordered]@{}) 'layers'
Write-Output ("LAYERS: {0}" -f ((Get-Field (Get-Field $layers 'payload') 'result') | ConvertTo-Json -Depth 6 -Compress))
$ids = [ordered]@{
    fr   = @('FR-GUESTADMIN-031', 'FR-IDENTITY-018', 'FR-PLAYERPROFILE-002', 'FR-ADMINPAGES-023', 'FR-PHONEINSTALL-026')
    tr   = @('TR-GITHUB-ADMIN-043', 'TR-IDENTITY-AUTHENTICATION-016', 'TR-PWA-INSTALLATION-036', 'TR-PWA-CACHEPRIVACY-037')
    test = @('TEST-GITHUBADMIN-149', 'TEST-ADMINUI-136', 'TEST-PWAINSTALL-137', 'TEST-PWAPRIVACY-138', 'TEST-IDENTITYAUTHENTICATION-116')
}
$methods = @{ fr = 'workflow.requirements.getFr'; tr = 'workflow.requirements.getTr'; test = 'workflow.requirements.getTest' }
foreach ($kind in $ids.Keys) {
    foreach ($id in $ids[$kind]) {
        $doc = Invoke-Read $methods[$kind] ([ordered]@{ id = $id }) $id
        $type = Get-Field $doc 'type'
        $result = Get-Field (Get-Field $doc 'payload') 'result'
        $item = Get-Field $result 'item'
        if ($null -eq $item) { $item = $result }
        if ($type -ne 'result' -or $null -eq $item) { Write-Output ("== {0}: type={1} (see receipt yaml)" -f $id, $type); continue }
        Write-Output ("== {0} status={1} scope={2}..{3} keys={4}" -f $id, (Get-Field $item 'status'), (Get-Field $item 'scopeStartLayerKey'), (Get-Field $item 'scopeEndLayerKey'), (($item.Keys | Sort-Object) -join ','))
        Write-Output ("   title: {0}" -f (Get-Field $item 'title'))
        $acs = @(Get-Field $item 'acceptanceCriteria')
        Write-Output ("   acceptanceCriteria={0}" -f $acs.Count)
        foreach ($ac in $acs) {
            if ($null -eq $ac) { continue }
            $acId = [string](Get-Field $ac 'id')
            $t = [string](Get-Field $ac 'text')
            $limit = if ($acId -match '^(GA|PWA)-') { 900 } else { 220 }
            if ($t.Length -gt $limit) { $t = $t.Substring(0, $limit) + '...' }
            Write-Output ("   - {0} sat={1}: {2}" -f $acId, (Get-Field $ac 'isSatisfied'), $t)
        }
        foreach ($f in @('notes', 'description', 'verification', 'testMethod')) {
            $v = [string](Get-Field $item $f)
            if ($v) { Write-Output ("   {0}: {1}" -f $f, $v.Substring(0, [Math]::Min(1200, $v.Length))) }
        }
    }
}
foreach ($fr in $ids['fr']) {
    $doc = Invoke-Read 'workflow.requirements.listMappings' ([ordered]@{ frId = $fr }) ("map-" + $fr)
    $result = Get-Field (Get-Field $doc 'payload') 'result'
    $items = @(Get-Field $result 'items')
    $edges = @($items | Where-Object { $null -ne $_ } | ForEach-Object { '{0}->{1}/{2}' -f (Get-Field $_ 'frId'), (Get-Field $_ 'trId'), (Get-Field $_ 'testId') })
    Write-Output ("MAP {0}: count={1} {2}" -f $fr, $edges.Count, ($edges -join '; '))
}

