            $ev = [string](Get-Field $ac 'evidence')
            if ($ev -and $acId -match $Focus) { Write-Output ("       evidence: {0}" -f $ev.Substring(0, [Math]::Min(500, $ev.Length))) }
        }
        foreach ($f in @('notes', 'description', 'verification', 'testMethod', 'objective')) {
            $v = [string](Get-Field $item $f)
            if ($v) { Write-Output ("   {0}: {1}" -f $f, $v.Substring(0, [Math]::Min(1800, $v.Length))) }
        }
    }
}
foreach ($fr in @($FrList -split ',')) {
    $doc = Invoke-Read -Method 'workflow.requirements.listMappings' -Params ([ordered]@{ frId = $fr }) -Label ('map-' + $fr)
    $items = @(Get-Field (Get-Field (Get-Field $doc 'payload') 'result') 'items' | Where-Object { $null -ne $_ })
    $edges = @($items | ForEach-Object { '{0}->{1}/{2}' -f (Get-Field $_ 'frId'), (Get-Field $_ 'trId'), (Get-Field $_ 'testId') })
    Write-Output ("MAP {0}: count={1} {2}" -f $fr, $edges.Count, ($edges -join '; '))
}

